<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
$events=all('SELECT id,name FROM events ORDER BY starts_at DESC');$id=(int)($_GET['event_id']??0);$mid=(int)($_GET['material_id']??0);$state=trim($_GET['status']??'');$cat=trim($_GET['category']??'');$delivery=trim($_GET['delivery']??'');$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$search=trim($_GET['search']??'');$city=trim($_GET['city']??'');$attended=trim($_GET['attended']??'');$certificate=trim($_GET['certificate']??'');
$materials=all('SELECT m.id,CONCAT(e.name,\' · \',m.name) name FROM materials m JOIN events e ON e.id=m.event_id'.($id?' WHERE m.event_id=?':''),$id?[$id]:[]);
$where=['1=1'];$args=[];$m=null;$carrera=trim($_GET['carrera']??'');if($carrera!==''){$where[]='r.carrera=?';$args[]=$carrera;}
if($id){$where[]='r.event_id=?';$args[]=$id;}if($mid){$m=one('SELECT * FROM materials WHERE id=?',[$mid]);if($m){$where[]='r.event_id=?';$args[]=$m['event_id'];}}
foreach(['status'=>$state,'category'=>$cat] as $col=>$v)if($v!==''){$where[]='r.'.$col.'=?';$args[]=$v;}
if($city!==''){$where[]='r.city LIKE ?';$args[]='%'.$city.'%';}if($search!==''){$where[]='(CONCAT(r.first_name,\' \',r.last_name) LIKE ? OR r.ci LIKE ?)';array_push($args,'%'.$search.'%','%'.$search.'%');}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='r.created_at>=?';$args[]=$from.' 00:00:00';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='r.created_at<=?';$args[]=$to.' 23:59:59';}
if(in_array($attended,['yes','no'],true))$where[]='r.attended_at IS '.($attended==='yes'?'NOT ':'').'NULL';if(in_array($certificate,['yes','no'],true))$where[]='r.certificate_issued_at IS '.($certificate==='yes'?'NOT ':'').'NULL';
$pick='0';if($m){$pick='(SELECT COALESCE(SUM(quantity),0) FROM deliveries d WHERE d.registration_id=r.id AND d.material_id='.(int)$mid.')';if($delivery==='picked')$where[]=$pick.'>0';if($delivery==='none')$where[]=$pick.'=0';if($delivery==='pending')$where[]=$pick.'<'.(int)$m['allowance'];if($delivery==='complete')$where[]=$pick.'>='.(int)$m['allowance'];}
$sql='SELECT r.*,e.name event_name,'.$pick.' picked FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where).' ORDER BY e.name,r.last_name,r.first_name';
$head=['Registro','Evento','Nombres','Apellidos','CI','Ciudad','Carrera','Categoría','Correo','Celular','Estado','Tarifa Bs','Cobrado Bs','Saldo Bs','Forma de pago','Registro fecha','Pago fecha','Asistencia','Certificado'];if($m)$head=array_merge($head,['Material','Asignado','Recogió','Pendiente']);
$values=function(array $r) use($m):array{$v=[$r['id'],$r['event_name'],$r['first_name'],$r['last_name'],$r['ci'],$r['city'],$r['carrera'],$r['category'],$r['email'],$r['phone'],$r['status'],$r['price'],$r['monto_cobrado'],max(0,$r['price']-$r['monto_cobrado']),$r['payment_method'],$r['created_at'],$r['paid_at'],$r['attended_at'],$r['certificate_issued_at']];if($m)$v=array_merge($v,[$m['name'],$m['allowance'],$r['picked'],max(0,$m['allowance']-$r['picked'])]);return $v;};
if(($_GET['export']??'')==='csv') {
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="reporte_unior.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$head,';');$stmt=q($sql,$args);while($r=$stmt->fetch()){$v=array_map(function($x){$s=(string)($x??'');return preg_match('/^[\s]*[=+@-]/u',$s)?"'".$s:$s;},$values($r));fputcsv($out,$v,';');}fclose($out);exit;
}
headerPage('Reportes de participantes y entregas'); ?>
<div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="reports"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column($events,'name','id'),(string)$id);?></div><div class="col-md-4"><?php selectField('material_id','Material',[0=>'Seleccione material']+array_column($materials,'name','id'),(string)$mid);?></div><div class="col-md-4"><?php selectField('delivery','Entrega',[''=>'Todos','picked'=>'Recogieron al menos una unidad','none'=>'No recogieron','pending'=>'Con unidades pendientes','complete'=>'Entrega completa'],$delivery);?></div><div class="col-md-3"><?php selectField('status','Estado de pago',[''=>'Todos','Pagado'=>'Pagado','Pendiente'=>'Pendiente','En revisión'=>'En revisión','Rechazado'=>'Rechazado','Anulado'=>'Anulado'],$state);?></div><div class="col-md-3"><?php selectField('carrera','Carrera',[''=>'Todas']+carrerasInscripcion(),$carrera);selectField('category','Categoría',[''=>'Todos','Estudiante'=>'Estudiante','Profesional'=>'Profesional','Estudiante BTH'=>'Estudiante BTH','UNIOR'=>'UNIOR'],$cat);?></div><div class="col-md-3"><?php field('from','Inscripción desde',$from,'date',false);?></div><div class="col-md-3"><?php field('to','Inscripción hasta',$to,'date',false);?></div><div class="col-md-3"><?php field('search','Nombre o CI',$search,'text',false);?></div><div class="col-md-3"><?php field('city','Ciudad',$city,'text',false);?></div><div class="col-md-3"><?php selectField('attended','Asistencia',[''=>'Todos','yes'=>'Asistieron','no'=>'Sin asistencia'],$attended);?></div><div class="col-md-3"><?php selectField('certificate','Certificado',[''=>'Todos','yes'=>'Emitido','no'=>'Sin emitir'],$certificate);?></div></div><button class="btn btn-primary">Generar reporte</button> <button class="btn btn-success" name="export" value="csv">Exportar Excel (CSV)</button> <button class="btn btn-outline-primary" type="button" onclick="print()">Imprimir / PDF</button><p class="mt-3">Seleccione un evento y filtre para actualizar su lista de materiales. Para pendientes de entrega con derecho a recibir materiales, filtre también por estado Pagado.</p></form></div>
<?php
$rows=all($sql,$args);$income=0;$tariffTotal=0;$pickedTotal=0;$pendingTotal=0;foreach($rows as $r){$income+=(float)$r['monto_cobrado'];$tariffTotal+=(float)$r['price'];if($m){$pickedTotal+=(int)$r['picked'];$pendingTotal+=max(0,$m['allowance']-$r['picked']);}}
?>
<div class="card p-4"><h3>UNIOR · Reporte de inscripciones</h3><p>Generado: <?=e(date('d/m/Y H:i'))?> · <?=count($rows)?> participantes · Tarifas registradas: <?=money($tariffTotal)?> · Cobrado: <?=money($income)?></p><?php if($m):?><p>Material: <?=e($m['name'])?> · Unidades recogidas: <?=$pickedTotal?> · Unidades pendientes: <?=$pendingTotal?></p><?php endif?><div class="table-responsive"><table class="table table-sm table-bordered"><thead><tr><?php foreach($head as $h)echo '<th>'.e($h).'</th>';?> <th class="no-print">Cobrar / recibos</th></tr></thead><tbody><?php foreach($rows as $r){echo '<tr>';foreach($values($r) as $v)echo '<td>'.e($v).'</td>';echo '<td class="no-print">';recibosReporte($r);echo '</td></tr>';}?></tbody></table></div></div>
<?php footerPage();
